//
// Metaclass factory and property bindings of the XMI importer.
// (Private header of the sysmlv2parser library. The tables are in XmiBindings.generated.cpp, generated by
// filehandling/tools/generate_xmi_bindings.py.)
//
//---------------------------------------------------------
// Constants, Definitions, Pragmas
//---------------------------------------------------------
#pragma once
//---------------------------------------------------------
// External Classes
//---------------------------------------------------------
#include <cerrno>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <charconv>
#include <limits>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <type_traits>
#include <vector>
//---------------------------------------------------------
// Internal Classes
//---------------------------------------------------------
#include <kerml/core/classifiers/Classifier.h>
#include <kerml/core/features/Feature.h>
#include <kerml/core/types/Type.h>
#include <kerml/root/elements/Element.h>
#include <sysmlv2/resolution/ResolutionData.h>
//---------------------------------------------------------

namespace SysMLv2::Files::Xmi {

    using ElementPtr = std::shared_ptr<KerML::Entities::Element>;

    /// The kind of value a property of an XMI element holds.
    enum class PropertyKind {
        Boolean,
        Integer,
        Real,
        String,
        Enumeration,
        Reference
    };

    /**
     * One stored property of a metaclass: how it is written in an XMI file (attribute or reference tag of the same name) and the
     * setter that stores a value in the model.
     */
    struct PropertyBinding {
        std::string_view name;
        PropertyKind kind;
        /// Multiplicity above one: a list of values (references: space separated ids in an attribute or repeated tags).
        bool many;
        /// The metaclass that declares the property.
        std::string_view declaredIn;
        /// Reference: the metaclass the target must have. Enumeration: the name of the enumeration.
        std::string_view target;
        /// Reference: the kind of placeholder that stands in for a target that cannot be found (valid if canPlaceholder).
        ReferenceKind placeholder;
        bool canPlaceholder;
        /// Boolean, Integer, Real, String, Enumeration: parses the text and stores it; false if the text is not a valid value.
        bool (*setValue)(KerML::Entities::Element& element, const std::string& text);
        /// Reference: stores the targets (exactly one for a single valued property); false (and an error text) if a target does not
        /// have the metaclass the property expects.
        bool (*setReferences)(KerML::Entities::Element& element, const std::vector<ElementPtr>& targets, std::string& error);
        /// Boolean, Integer, Real, String, Enumeration: the value as it is written in an XMI file; nullopt if the property has no value
        /// or the value equals the default of the metamodel (it is not written then).
        std::optional<std::string> (*getValue)(const KerML::Entities::Element& element);
        /// Reference: the targets in order (empty if there are none). Placeholders of unresolved references are included, see isUnresolved().
        std::vector<ElementPtr> (*getReferences)(const KerML::Entities::Element& element);
    };

    /// A concrete or abstract metaclass of KerML or SysML with its factory and the properties it has (inherited ones included).
    struct MetaclassBinding {
        std::string_view name;
        bool isAbstract;
        /// Null for an abstract metaclass.
        ElementPtr (*create)();
        /// Null terminated.
        const PropertyBinding* const* properties;
        std::size_t propertyCount;

        const PropertyBinding* find(std::string_view propertyName) const {
            for (std::size_t i = 0; i < propertyCount; ++i) {
                if (properties[i]->name == propertyName) return properties[i];
            }
            return nullptr;
        }
    };

    /// The metaclass of that name (without the "sysml:" prefix of XMI), or null if there is no such KerML or SysML metaclass.
    const MetaclassBinding* findMetaclass(std::string_view name);
    /// True for the name of a derived property (or of the structure the importer wires itself): it is not bound and not read.
    bool isDerivedProperty(std::string_view name);
    /// Number of metaclasses in the table.
    std::size_t metaclassCount();

    // ---------------------------------------------------------------------------------------------------------------
    // Helpers of the generated code
    // ---------------------------------------------------------------------------------------------------------------

    template <class T>
    T& as(KerML::Entities::Element& element) {
        return dynamic_cast<T&>(element);
    }

    inline bool parseBoolean(const std::string& text, bool& value) {
        if (text == "true" || text == "1") {
            value = true;
            return true;
        }
        if (text == "false" || text == "0") {
            value = false;
            return true;
        }
        return false;
    }

    inline bool parseInteger(const std::string& text, std::int64_t& value) {
        if (text.empty()) return false;
        errno = 0;
        char* end = nullptr;
        const long long parsed = std::strtoll(text.c_str(), &end, 10);
        if (errno != 0 || end == nullptr || *end != '\0') return false;
        value = static_cast<std::int64_t>(parsed);
        return true;
    }

    inline bool parseReal(const std::string& text, double& value) {
        if (text.empty()) return false;
        // (the xsd:double literals of the special values)
        if (text == "INF" || text == "+INF") {
            value = std::numeric_limits<double>::infinity();
            return true;
        }
        if (text == "-INF") {
            value = -std::numeric_limits<double>::infinity();
            return true;
        }
        if (text == "NaN") {
            value = std::numeric_limits<double>::quiet_NaN();
            return true;
        }
        errno = 0;
        char* end = nullptr;
        const double parsed = std::strtod(text.c_str(), &end);
        if (errno != 0 || end == nullptr || *end != '\0') return false;
        value = parsed;
        return true;
    }

    // ---------------------------------------------------------------------------------------------------------------
    // Helpers of the generated getters (XMI writer)
    // ---------------------------------------------------------------------------------------------------------------

    inline std::string formatBoolean(bool value) { return value ? "true" : "false"; }

    inline std::string formatInteger(long long value) { return std::to_string(value); }

    /// The shortest text that reads back as the same double; the special values as the xsd:double literals INF, -INF and NaN.
    inline std::string formatReal(double value) {
        if (std::isnan(value)) return "NaN";
        if (std::isinf(value)) return value < 0 ? "-INF" : "INF";
        // Shortest %g text (15..17 significant digits) that reads back as the same double. Not std::to_chars(double): libc++ offers
        // it only from macOS 13.3. snprintf honours the C locale's decimal point, so a ',' (or any single-character separator) is mapped to '.'.
        char buffer[64];
        for (int precision = 15; precision <= 17; ++precision) {
            std::snprintf(buffer, sizeof(buffer), "%.*g", precision, value);
            if (precision == 17 || std::strtod(buffer, nullptr) == value) break;
        }
        std::string text(buffer);
        for (char& c : text) if (c == ',') c = '.';
        return text;
    }

    inline std::string formatString(const std::string& value) { return value; }

    /// The XMI text of a value, or nullopt if it equals the default (@p defaultText, null: there is none).
    template <class T, class Format>
    std::optional<std::string> valueText(const T& value, Format format, const char* defaultText) {
        std::string text = format(value);
        if (defaultText != nullptr && text == defaultText) return std::nullopt;
        return text;
    }

    template <class T, class Format>
    std::optional<std::string> valueText(const std::optional<T>& value, Format format, const char* defaultText) {
        if (!value) return std::nullopt;
        return valueText(*value, format, defaultText);
    }

    /// The targets of a reference property, whichever way the getter of the class delivers them.
    template <class T>
    std::vector<ElementPtr> toElements(const std::shared_ptr<T>& value) {
        return value ? std::vector<ElementPtr>{value} : std::vector<ElementPtr>{};
    }

    template <class T>
    std::vector<ElementPtr> toElements(const std::optional<std::shared_ptr<T>>& value) {
        return value ? toElements(*value) : std::vector<ElementPtr>{};
    }

    template <class T>
    std::vector<ElementPtr> toElements(const std::vector<std::shared_ptr<T>>& values) {
        std::vector<ElementPtr> result;
        result.reserve(values.size());
        for (const auto& value : values) {
            if (value) result.push_back(value);
        }
        return result;
    }

    /// Casts a reference target to the class a setter expects; on failure @p error names the expected metaclass.
    template <class T>
    bool castReference(const ElementPtr& value, std::shared_ptr<T>& out, const char* expected, std::string& error) {
        out = std::dynamic_pointer_cast<T>(value);
        if (!out) {
            error = std::string("the target is not a ") + expected + (value ? " but a " + value->getType() : std::string(" (null)"));
            return false;
        }
        return true;
    }

    /// An unresolved stand-in of the class T (the ends of the relationships without a default constructor).
    template <class T>
    std::shared_ptr<T> placeholder() {
        ReferenceKind kind = ReferenceKind::Element;
        if constexpr (std::is_same_v<T, KerML::Entities::Feature>) kind = ReferenceKind::Feature;
        else if constexpr (std::is_same_v<T, KerML::Entities::Classifier>) kind = ReferenceKind::Classifier;
        else if constexpr (std::is_same_v<T, KerML::Entities::Type>) kind = ReferenceKind::Type;
        return std::dynamic_pointer_cast<T>(makePlaceholder(kind, ""));
    }
}
